import { BrowserWindow, dialog, net, protocol, type OpenDialogOptions } from 'electron'
import { randomUUID } from 'crypto'
import { copyFileSync, existsSync, mkdirSync, readdirSync, rmSync, statSync } from 'fs'
import { extname, join } from 'path'
import { pathToFileURL } from 'url'
import { getDb } from '../db/connection'
import { photosDir } from '../paths'

/** Photo file names are generated by us; anything else is rejected (blocks path tricks like "../"). */
export const isSafeName = (f: string): boolean => /^[A-Za-z0-9._-]+$/.test(f) && !f.includes('..')

/** GA-2: copies the chosen image into the photos folder and returns just the file name. */
export async function pickPhoto(): Promise<string | null> {
  const opts: OpenDialogOptions = {
    title: 'Choose a photo',
    properties: ['openFile'],
    filters: [{ name: 'Photos', extensions: ['jpg', 'jpeg', 'png', 'webp', 'gif', 'bmp'] }]
  }
  const win = BrowserWindow.getFocusedWindow()
  const r = win ? await dialog.showOpenDialog(win, opts) : await dialog.showOpenDialog(opts)
  if (r.canceled || !r.filePaths[0]) return null
  mkdirSync(photosDir(), { recursive: true })
  const name = randomUUID() + extname(r.filePaths[0]).toLowerCase()
  copyFileSync(r.filePaths[0], join(photosDir(), name))
  return name
}

export function deletePhotoFiles(files: string[]): void {
  for (const f of files) if (isSafeName(f)) rmSync(join(photosDir(), f), { force: true })
}

/** Serves photo://local/<file> from the photos folder. A missing file answers 404, which the UI
 *  turns into the "Photo not found" placeholder (GA-7). Call after app is ready. */
export function registerPhotoProtocol(): void {
  protocol.handle('photo', (req) => {
    const file = decodeURIComponent(new URL(req.url).pathname.slice(1))
    const full = join(photosDir(), file)
    if (!isSafeName(file) || !existsSync(full)) return new Response(null, { status: 404 })
    return net.fetch(pathToFileURL(full).toString())
  })
}

/** Removes photos left behind when someone picked a photo but cancelled the form.
 *  Deliberately cautious: only files older than a day, and never when the database lists no photos at all. */
export function cleanOrphanPhotos(): void {
  try {
    const used = new Set(getDb().prepare('SELECT file_name FROM garment_photos').all().map((r) => (r as { file_name: string }).file_name))
    if (used.size === 0) return
    const cutoff = Date.now() - 24 * 3600 * 1000
    for (const f of readdirSync(photosDir())) {
      const full = join(photosDir(), f)
      if (!used.has(f) && isSafeName(f) && statSync(full).mtimeMs < cutoff) rmSync(full, { force: true })
    }
  } catch {
    /* cleanup is best-effort */
  }
}
